                    <div class="text-xs text-base-content/50 uppercase">Duration</div>
                    <div class="text-lg font-bold">{{ formatDuration(req.token_event?.duration_seconds) }}</div>
                  </div>
                  <div class="space-y-1 p-2 rounded bg-base-100 border border-base-300">
                    <div class="text-xs text-base-content/50 uppercase">Cost</div>
                    <div class="text-lg font-bold text-primary">{{ formatCost(req.token_event?.total_cxjcoins) }}</div>
