                  </div>
                </div>

                <!-- Cache Info -->
                <div v-if="req.token_event?.cache_hits !== undefined" class="grid grid-cols-3 gap-3 pt-2 border-t border-base-300">
                  <div class="space-y-1">
                    <div class="text-xs text-base-content/50 uppercase">Cache Hits</div>
                    <div class="font-bold text-success">{{ req.token_event?.cache_hits || 0 }}</div>
                  </div>
                  <div class="space-y-1">
                    <div class="text-xs text-base-content/50 uppercase">Cache Misses</div>
                    <div class="font-bold text-warning">{{ req.token_event?.cache_misses || 0 }}</div>
                  </div>
                  <div class="space-y-1">
                    <div class="text-xs text-base-content/50 uppercase">Hit Rate</div>
                    <div class="font-bold">{{ req.token_event?.cache_hit_rate || '0%' }}</div>
                  </div>
                </div>

                <!-- Messages for this request -->
                <div v-if="requestMessages[idx] && (requestMessages[idx].llm.length || requestMessages[idx].tool.length)" class="pt-2 border-t border-base-300 space-y-3">
                  <div class="text-sm font-semibold text-base-content/70">Associated Messages</div>

                  <!-- LLM Messages -->
                  <div v-if="requestMessages[idx].llm.length" class="space-y-2">
                    <div class="text-xs font-semibold text-secondary/80 flex items-center gap-1">
                      <i class="fa-solid fa-comments text-xs"></i>
                      LLM Response ({{ requestMessages[idx].llm.length }})
                    </div>
                    <div v-for="(msg, mIdx) in requestMessages[idx].llm" :key="`llm-${idx}-${mIdx}`" class="rounded-lg bg-secondary/10 border border-secondary/20 p-3">
                      <div class="text-xs text-base-content/60 mb-2">
                        <span class="font-semibold capitalize">{{ msg.role }}</span>
                        <span class="ml-2">{{ formatDate(msg.timestamp) }}</span>
                      </div>
                      <div class="text-sm text-base-content/80 whitespace-pre-wrap break-words max-h-40 overflow-y-auto">
                        {{ msg.content }}
                      </div>
                    </div>
                  </div>

                  <!-- Tool Messages -->
                  <div v-if="requestMessages[idx].tool.length" class="space-y-2">
                    <div class="text-xs font-semibold text-accent/80 flex items-center gap-1">
                      <i class="fa-solid fa-wrench text-xs"></i>
                      Tool Calls ({{ requestMessages[idx].tool.length }})
                    </div>
                    <div v-for="(msg, mIdx) in requestMessages[idx].tool" :key="`tool-${idx}-${mIdx}`" class="rounded-lg bg-accent/10 border border-accent/20 p-3 space-y-2">
                      <div class="text-xs font-semibold text-accent">{{ msg.tool_name }}</div>
                      <div v-if="msg.arguments" class="space-y-1">
                        <div class="text-xs text-base-content/60">Arguments:</div>
                        <div class="bg-base-100 rounded p-2 font-mono text-xs text-base-content/70 overflow-x-auto max-h-24 overflow-y-auto">
                          {{ typeof msg.arguments === 'string' ? msg.arguments : formatJson(msg.arguments) }}
                        </div>
                      </div>
                      <div v-if="msg.result" class="space-y-1">
                        <div class="text-xs text-base-content/60">Result:</div>
                        <div class="bg-base-100 rounded p-2 font-mono text-xs text-base-content/70 overflow-x-auto max-h-24 overflow-y-auto">
                          {{ typeof msg.result === 'string' ? msg.result : formatJson(msg.result) }}
                        </div>
                      </div>
                    </div>
                  </div>
                </div>

                <!-- Loading messages indicator -->
                <div v-if="messagesLoading[idx]" class="flex items-center gap-2 pt-2 border-t border-base-300">
                  <span class="loading loading-spinner loading-sm text-primary"></span>
                  <span class="text-xs text-base-content/60">Loading messages...</span>
                </div>
              </div>
            </div>
          </div>

          <!-- TOOL CALLS TAB -->
          <div v-if="activeTab === 'tools'" class="space-y-4">
            <div v-if="!toolCalls.length" class="text-center py-8 text-base-content/50">
              <i class="fa-solid fa-inbox text-2xl mb-2 block opacity-30"></i>
              No tool calls found
            </div>

            <div v-for="(tool, idx) in toolCalls" :key="idx" class="rounded-xl border border-base-300 overflow-hidden">
              <button
                @click="toggleSection(`tool-${idx}`)"
                class="w-full flex items-center justify-between px-4 py-3 bg-base-200 border-b border-base-300 hover:bg-base-300 transition-colors"
              >
                <div class="flex items-center gap-3 min-w-0 flex-1">
