                  <div class="flex items-center gap-2 min-w-0">
                    <span class="text-sm font-semibold">{{ tool.tool_event?.name }}</span>
                    <span v-if="tool.tool_event?.success" class="badge badge-success badge-sm">Success</span>
                    <span v-else class="badge badge-error badge-sm">Failed</span>
