                </div>
                <div class="flex items-center gap-2 shrink-0">
                  <span class="text-xs text-base-content/50">{{ formatDuration(tool.tool_event?.time_taken) }}</span>
                  <span class="text-xs font-mono text-base-content/30">{{ formatDate(tool.tool_event?.timestamp) }}</span>
