                    <span class="text-base-content/50 font-semibold uppercase w-20">Request ID:</span>
                    <span class="font-mono text-base-content/70 break-all">{{ tool.tool_event?.request_id }}</span>
                  </div>
                  <div class="flex items-center gap-2">
                    <span class="text-base-content/50 font-semibold uppercase w-20">Project:</span>
                    <span class="text-base-content/70">{{ tool.tool_event?.project_name }}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  props: {
    chatSession: { type: Object, default: null },
    loading: { type: Boolean, default: false },
    isAdmin: { type: Boolean, default: false }
  },
  emits: ['close'],
  data() {
    return {
      activeTab: 'overview',
      expandedSections: {},
      requestMessages: {},
      messagesLoading: {},
      tabs: [
        { id: 'overview', label: 'Overview', icon: 'fa-chart-pie' },
        { id: 'metrics', label: 'Metrics', icon: 'fa-gauge' },
        { id: 'requests', label: 'LLM Requests', icon: 'fa-message' },
        { id: 'tools', label: 'Tool Calls', icon: 'fa-wrench' }
      ]
    }
  },
  computed: {
    hasError() {
      return !!this.chatSession?.chat_session?.error
    },
    chatInfo() {
      return this.chatSession?.chat_session
    },
    metricsInfo() {
      return this.chatSession?.metrics
    },
    llmRequests() {
      return this.chatSession?.llm_requests || []
    },
    toolCalls() {
      return this.chatSession?.tool_calls || []
    },
    toolMetrics() {
      return this.chatSession?.tool_metrics
    }
  },
  methods: {
    toggleSection(key) {
      this.expandedSections[key] = !this.expandedSections[key]
      this.$set(this.expandedSections, key, this.expandedSections[key])
    },
    async toggleRequestExpansion(idx) {
      const key = `req-${idx}`
      this.expandedSections[key] = !this.expandedSections[key]
      this.$set(this.expandedSections, key, this.expandedSections[key])

      // CHANGED: Load messages on expansion using request_id from token_event
      if (this.expandedSections[key] && !this.requestMessages[idx]) {
        await this.loadMessagesForRequest(idx)
      }
    },
    async loadMessagesForRequest(idx) {
      // CHANGED: Use request_id-specific endpoint instead of timestamp-based matching
      if (!this.chatSession?.chat_session?.chat_id) return

      const req = this.llmRequests[idx]
      const requestId = req?.token_event?.request_id

      if (!requestId) {
        // Fallback if no request_id
        this.requestMessages[idx] = { llm: [], tool: [] }
        this.$set(this.requestMessages, idx, this.requestMessages[idx])
        return
      }

      this.messagesLoading[idx] = true
      this.$set(this.messagesLoading, idx, true)

      try {
        const chatId = this.chatSession.chat_session.chat_id
        const isAdmin = this.isAdmin

        // ADDED: Call new endpoint to fetch messages for this specific request
        const result = isAdmin
          ? await this.$project.$api.analytics.admin.chatSessionRequestMessages(chatId, requestId)
          : await this.$project.$api.analytics.chatSessionRequestMessages(chatId, requestId)

        // Transform backend response
        const llm = (result.llm_messages || []).map(msg => ({
          type: 'llm',
          ...msg,
          timestamp: msg.timestamp || msg.created_at
        }))

        const tool = (result.tool_messages || []).map(msg => ({
          type: 'tool',
          ...msg,
          timestamp: msg.timestamp || msg.created_at
        }))

        this.requestMessages[idx] = {
          llm: llm,
          tool: tool
        }
        this.$set(this.requestMessages, idx, this.requestMessages[idx])
      } catch (err) {
        console.error('Failed to load request messages:', err)
        this.requestMessages[idx] = { llm: [], tool: [] }
        this.$set(this.requestMessages, idx, this.requestMessages[idx])
      } finally {
        this.messagesLoading[idx] = false
        this.$set(this.messagesLoading, idx, false)
      }
    },
    formatJson(obj) {
      try {
        return JSON.stringify(obj, null, 2)
      } catch {
        return String(obj)
      }
    },
    formatDuration(seconds) {
      return seconds ? `${seconds.toFixed(2)}s` : '—'
    },
    formatCost(coins) {
      return coins ? `${coins.toFixed(5)} CXJ` : '—'
    },
    formatDate(timestamp) {
      if (typeof timestamp === 'number') {
        return new Date(timestamp * 1000).toLocaleString()
      }
      return new Date(timestamp).toLocaleString()
    }
  }
}
</script>
```

| File Path | Action | Component / Section | Change Description |
| :--- | :--- | :--- | :--- |
| `src/components/logs/LogEntryDetail.vue` | Modify | Data | Removed `messages` and `messagesLoaded` properties; kept `requestMessages` and `messagesLoading` for per-request tracking |
| `src/components/logs/LogEntryDetail.vue` | Modify | `loadMessagesForRequest()` method | Replaced timestamp-based message matching with request ID-specific endpoint call; now calls `chatSessionRequestMessages(chatId, requestId)` for each request |
| `src/components/logs/LogEntryDetail.vue` | Modify | Message loading logic | Each request now loads its own messages independently when expanded, eliminating global message load |

---

## Summary of Changes

**Key improvements:**
1. ✅ Added two new API endpoints for fetching messages by request ID
2. ✅ Replaced inefficient timestamp-based matching with precise request ID lookup
3. ✅ Each LLM request loads its messages independently on expansion
4. ✅ Admin and user scopes both supported
5. ✅ Maintains backward compatibility with existing endpoints

